import{_ as s,o as a,c as t,a2 as i}from"./chunks/framework.ChTAMbUy.js";const c=JSON.parse('{"title":"Component Versions","description":"","frontmatter":{},"headers":[],"relativePath":"1.9/platform/component_versions.md","filePath":"versions/1.9/platform/component_versions.md","lastUpdated":1791568428000}'),n={name:"1.9/platform/component_versions.md"};function r(o,e,l,h,p,d){return a(),t("div",null,[...e[0]||(e[0]=[i(`<h1 id="component-versions" tabindex="-1">Component Versions <a class="header-anchor" href="#component-versions" aria-label="Permalink to &quot;Component Versions&quot;">​</a></h1><p>prokube bundles several upstream components. Use this page to find the versions running in your deployment and to choose matching upstream documentation, SDKs, and examples.</p><p>Do not assume that every prokube deployment runs the same component versions. Managed, self-managed, staging, and customer-specific deployments can differ.</p><h2 id="release-defaults" tabindex="-1">Release Defaults <a class="header-anchor" href="#release-defaults" aria-label="Permalink to &quot;Release Defaults&quot;">​</a></h2><p>Component versions shipped with prokube 1.9:</p><table tabindex="0"><thead><tr><th>Component</th><th>Version</th></tr></thead><tbody><tr><td><a href="https://github.com/kubeflow/manifests/releases" target="_blank" rel="noreferrer">Kubeflow Manifests</a></td><td>26.03.1</td></tr><tr><td><a href="https://www.kubeflow.org/docs/components/pipelines/" target="_blank" rel="noreferrer">Kubeflow Pipelines</a> backend</td><td>2.16.1</td></tr><tr><td><a href="https://kubeflow-pipelines.readthedocs.io/" target="_blank" rel="noreferrer">KFP SDK</a> (recommended)</td><td>2.15.0</td></tr><tr><td><a href="https://kserve.github.io/website/" target="_blank" rel="noreferrer">KServe</a></td><td>v0.18.0</td></tr><tr><td><a href="https://mlflow.org/docs/latest/" target="_blank" rel="noreferrer">MLflow</a></td><td>3.10.0</td></tr></tbody></table><p>Each component name links to its upstream documentation.</p><p>The recommended KFP SDK version is pinned in the prokube notebook images. If you install a different version, make sure it is compatible with the KFP backend.</p><p>These are release defaults. A deployment can differ, for example after an administrator switches the KServe source or upgrades a component separately. For releases before 1.9, see the <a href="https://docs.prokube.ai/latest/user_docs/component_versions/" target="_blank" rel="noreferrer">legacy component version matrix</a>.</p><h2 id="check-your-deployment" tabindex="-1">Check Your Deployment <a class="header-anchor" href="#check-your-deployment" aria-label="Permalink to &quot;Check Your Deployment&quot;">​</a></h2><p>The prokube version is shown at the bottom of the pkui sidebar.</p><p>The <code>paas-version</code> ConfigMap in the <code>prokube</code> namespace records the release defaults of the installed version. Reading it requires access to the <code>prokube</code> namespace, which usually only administrators have:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> configmap</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> paas-version</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> prokube</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> yaml</span></span></code></pre></div><p>The prokube version is stored under <code>paasVersion</code>. The component keys match the table above, for example <code>kfpBackendVersion</code> and <code>kserveVersion</code>. If you cannot read the ConfigMap, ask your administrator.</p><h2 id="check-component-versions" tabindex="-1">Check Component Versions <a class="header-anchor" href="#check-component-versions" aria-label="Permalink to &quot;Check Component Versions&quot;">​</a></h2><p>Useful inspection commands:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> deployments,statefulsets</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pods</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> custom-columns=NAMESPACE:.metadata.namespace,NAME:.metadata.name,IMAGE:.spec.containers[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">*</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">].image</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> inferenceservices</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> clusterstoragecontainers</span></span></code></pre></div><p>For KServe serving runtimes, inspect the runtime or the model pod image:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> servingruntime,clusterservingruntime</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -A</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">kubectl</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> get</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> pod</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">model-po</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">d</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -n</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> &lt;</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">workspac</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">e</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -o</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> jsonpath=&#39;{.spec.containers[*].image}{&quot;\\n&quot;}&#39;</span></span></code></pre></div><p>For Kubeflow Pipelines, use the backend version when choosing a KFP SDK. KFP SDK and backend versions should be compatible; examples written for a newer SDK can fail against an older backend.</p><h2 id="why-versions-matter" tabindex="-1">Why Versions Matter <a class="header-anchor" href="#why-versions-matter" aria-label="Permalink to &quot;Why Versions Matter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Area</th><th>Why it matters</th></tr></thead><tbody><tr><td>Kubeflow Pipelines</td><td>SDK DSL features, compiled YAML format, and <code>kfp-kubernetes</code> helpers depend on backend compatibility.</td></tr><tr><td>KServe</td><td>InferenceService fields, storage initializers, local model cache, and autoscaling annotations vary by version.</td></tr><tr><td>MLflow</td><td>Client API behavior, model registry features, and authentication plugin behavior vary by version.</td></tr><tr><td>Knative</td><td>Autoscaling, revisions, and routing behavior affect KServe serverless deployments.</td></tr><tr><td>Kubernetes</td><td>API versions, Pod Security behavior, CSI features, and resource semantics depend on cluster version.</td></tr></tbody></table><p>When debugging, include both the prokube version and the relevant upstream component versions in support requests.</p><h2 id="related-pages" tabindex="-1">Related Pages <a class="header-anchor" href="#related-pages" aria-label="Permalink to &quot;Related Pages&quot;">​</a></h2><ul><li><a href="./../mlops/pipelines.html">Pipelines</a></li><li><a href="./../mlops/model_serving.html">Model Serving</a></li><li><a href="./../mlops/mlflow.html">MLflow</a></li></ul>`,25)])])}const m=s(n,[["render",r]]);export{c as __pageData,m as default};
